/**
 * Unit tests for DurationFormatUtils.formatPeriod
 */
public class DurationFormatUtils_formatPeriod_TriageGen0Test {

    private static final TimeZone GMT = TimeZone.getTimeZone("GMT");
    private static final TimeZone EST = TimeZone.getTimeZone("EST");

    @Test
    public void testFormatPeriod_ShortDuration_UsesFormatDuration() {
        // Less than 28 days
        long start = 1000L;
        long end = 2000L; // 1 second diff
        // This should trigger the if (millis < 28 * DateUtils.MILLIS_PER_DAY) branch
        // formatDuration is called internally. Assuming format "s" returns "1" or "01"
        String result = DurationFormatUtils.formatPeriod(start, end, "s", false, GMT);
        assertEquals("1", result);
    }














}

