    public void testFormatPeriod_TimezoneShift() {
        // Test that timezone affects the calculation of hours/days
        long start = 1609459200000L; // 2021-01-01 00:00:00 GMT
        long end = 1609462800000L;   // 2021-01-01 01:00:00 GMT

        // In GMT it's 1 hour
        String resGmt = DurationFormatUtils.formatPeriod(start, end, "H 'hours'", false, GMT);
        assertEquals("1 hours", resGmt);

