/**
 * Unit tests for DurationFormatUtils.formatPeriod
 */
public class DurationFormatUtils_formatPeriod_TriageGen0Test {

    private static final TimeZone GMT = TimeZone.getTimeZone("GMT");
    private static final TimeZone EST = TimeZone.getTimeZone("EST");









    @Test
    public void testFormatPeriod_TokenAggregration_NoYears() {
        // Test the logic: if (!Token.containsTokenWithValue(tokens, y)) { if (Token.containsTokenWithValue(tokens, M)) ... }
        // This tests the "months += 12 * years" branch
        Calendar cal = Calendar.getInstance(GMT);
        cal.set(2020, Calendar.JANUARY, 1, 0, 0, 0);
        long start = cal.getTimeInMillis();

        cal.add(Calendar.YEAR, 1);
        cal.add(Calendar.MONTH, 1);
        long end = cal.getTimeInMillis();

        // Format only asks for months. 1 year 1 month should become 13 months.
        String result = DurationFormatUtils.formatPeriod(start, end, "M 'months'", false, GMT);
        assertEquals("13 months", result);
    }






}

