/**
 * Unit tests for DurationFormatUtils.formatPeriod
 */
public class DurationFormatUtils_formatPeriod_TriageGen0Test {

    private static final TimeZone GMT = TimeZone.getTimeZone("GMT");
    private static final TimeZone EST = TimeZone.getTimeZone("EST");











    @Test
    public void testFormatPeriod_TokenAggregration_NoMonthsNoYears() {
        // Test the logic: if (!Token.containsTokenWithValue(tokens, M)) { days += end.get(Calendar.DAY_OF_YEAR) - start.get(Calendar.DAY_OF_YEAR); ... }
        // This tests the fallback for days when years are present but months are not requested
        Calendar cal = Calendar.getInstance(GMT);
        cal.set(2020, Calendar.JANUARY, 1, 0, 0, 0);
        long start = cal.getTimeInMillis();

        cal.add(Calendar.YEAR, 1);
        long end = cal.getTimeInMillis();

        // Format only asks for days. 1 year should be ~365/366 days.
        String result = DurationFormatUtils.formatPeriod(start, end, "d 'days'", false, GMT);
        // Result is expected to be the total day count
        // 2020 was a leap year, so 366 days
        assertEquals("366 days", result);
    }




}

